mapper.select:
SELECT segment.session_id, segment.execution_id, segment.segment_id,
       segment.segment_ordinal, segment.trigger_event_id, segment.trigger_event_seq,
       segment.state, segment.terminal_event_id, segment.terminal_event_seq,
       UPPER(segment.terminal_reason) AS terminal_reason,
       segment.created_at, segment.updated_at
FROM t_session_execution_segments segment
INNER JOIN t_session_executions execution
        ON execution.session_id = segment.session_id
       AND execution.execution_id = segment.execution_id
WHERE segment.session_id = #{sessionId}
  AND segment.execution_id = #{executionId}
  AND execution.root_event_id = #{rootEventId}
  AND segment.segment_id = #{segmentId}
